// AUTO-GENERATED BY build.js - DO NOT EDIT
// foxai_cli_update Host Bundle（含内嵌 update-cli-tools.js）


const UPDATE_SCRIPT = "#!/usr/bin/env node

'use strict';

const { spawnSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const IS_WIN = process.platform === 'win32';

const TOOLS = [
  { id: 'claude',   name: 'Claude Code', pkg: '@anthropic-ai/claude-code',      bin: 'claude' },
  { id: 'codex',    name: 'Codex CLI',   pkg: '@openai/codex',                  bin: 'codex' },
  { id: 'gemini',   name: 'Gemini CLI',  pkg: '@google/gemini-cli',             bin: 'gemini' },
  { id: 'opencode', name: 'OpenCode',    pkg: 'opencode-ai',                    bin: 'opencode' },
  { id: 'pi',       name: 'Pi',          pkg: '@earendil-works/pi-coding-agent', bin: 'pi' },
];

function parseArgs(argv) {
  const opts = { check: false, json: false, only: null };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--check') opts.check = true;
    else if (a === '--json') opts.json = true;
    else if (a === '--only') {

      const v = argv[i + 1];
      if (v && !v.startsWith('--')) { opts.only = v; i++; }
      else { opts.only = ''; }  // 空字符串:在 main 里被当作 unknown 处理
    } else if (a.indexOf('--only=') === 0) {
      opts.only = a.slice(7);
    }
  }
  return opts;
}
const OPTS = parseArgs(process.argv);
const CHECK_ONLY = OPTS.check;
const EMIT_JSON = OPTS.json;

const onlySet = OPTS.only === null ? null : OPTS.only.split(',').map(function (s) { return s.trim(); });

function out(msg) { process.stdout.write(msg + '\n'); }

function run(cmd, args, timeoutMs) {
  return spawnSync(cmd, args, {
    encoding: 'utf8',
    shell: IS_WIN, // Windows 下 npm/npm.cmd、全局二进制需要经 cmd 解析
    timeout: timeoutMs || 0,
    maxBuffer: 16 * 1024 * 1024,
  });
}

function npm(args, timeoutMs) { return run('npm', args, timeoutMs); }

function NPM_ROOT_OF() {
  const res = npm(['root', '-g'], 60000);
  if (res.error || res.status !== 0) return '';
  return String(res.stdout || '').trim().split('\n').pop().trim();
}

const NPM_ROOT = NPM_ROOT_OF();

function installedVersion(pkgName) {
  try {
    const pj = path.join.apply(null, [NPM_ROOT].concat(pkgName.split('/'), ['package.json']));
    const v = JSON.parse(fs.readFileSync(pj, 'utf8')).version;
    return v ? String(v) : '';
  } catch (e) {
    return '';
  }
}

function latestVersion(pkgName) {
  const res = npm(['view', pkgName, 'version'], 90000);
  if (res.error || res.status !== 0) return '';
  const v = String(res.stdout || '').trim().split('\n').pop().trim();
  return v || '';
}

function binProbe(binName) {

  const res = run(binName, ['--version'], 60000);
  if (res.error || res.status !== 0) return { exists: false, version: '' };
  return { exists: true, version: String(res.stdout || '').trim().split('\n')[0] || '' };
}

function sanitize(s) {
  return String(s || '').replace(/[\n\r\t|]+/g, ' ').replace(/\|/g, '/').slice(0, 200);
}

function eaccHint(pkgName) {
  if (IS_WIN) return '全局 npm 目录无写权限，请检查 %APPDATA%\\npm 权限或以管理员运行';
  return '全局 npm 目录无写权限(EACCES)。方案A: sudo npm install -g ' + pkgName + '@latest；方案B(推荐): npm config set prefix ~/.npm-global 并把 ~/.npm-global/bin 加入 PATH';
}

function main() {
  if (!NPM_ROOT) {
    out('✗ 无法确定 npm 全局目录（npm root -g 失败），请确认已安装 Node.js/npm');
    process.exit(1);
  }

  const modeLabel = CHECK_ONLY ? '仅检查（--check，不做改动）' : '检查并自动更新';
  out('==============================================================');
  out(' FoxAI CLI 工具更新  [' + modeLabel + ']');
  out(' 系统: ' + process.platform + '  npm 全局目录: ' + NPM_ROOT);
  out(' 时间: ' + new Date().toLocaleString());
  out('==============================================================');

  let filteredTools = TOOLS;
  if (onlySet && onlySet.length > 0) {
    const knownIds = new Set(TOOLS.map(function (t) { return t.id; }));
    const unknown = onlySet.filter(function (id) { return !knownIds.has(id); });
    if (unknown.length > 0) {
      out('✗ --only 包含未知工具 id: ' + unknown.join(', ') + '（合法值: ' + Array.from(knownIds).join(', ') + '）');
      process.exit(2);
    }
    filteredTools = TOOLS.filter(function (t) { return onlySet.indexOf(t.id) !== -1; });
    if (filteredTools.length === 0) {
      out('✗ --only 过滤后没有可用工具');
      process.exit(2);
    }
  }

  out(['工具'.padEnd(9), '状态'.padEnd(13), '当前版本'.padEnd(11), '最新版本'.padEnd(11), '操作'].join(''));
  out('--------------------------------------------------------------');

  const results = [];
  const summary = {};
  const bump = (s) => { summary[s] = (summary[s] || 0) + 1; };

  for (const t of filteredTools) {
    const cur = installedVersion(t.pkg);
    const lat = latestVersion(t.pkg);
    let status = '', action = '', verFrom = cur || '-', verTo = lat || '-', err = '';

    if (!lat) {
      const bp = binProbe(t.bin);
      if (bp.exists) {
        status = 'external'; verFrom = bp.version || '-'; verTo = '-';
        action = '非 npm 渠道安装，跳过；且无法查询 registry';
      } else {
        status = 'unknown';
        action = '无法查询 npm registry（检查网络）';
      }
    } else if (!cur) {
      const bp = binProbe(t.bin);
      if (bp.exists) {

        status = 'external'; verFrom = bp.version || '-';
        action = '非 npm 渠道安装（如 brew/scoop），跳过；如需接管请先卸载原渠道版本';
      } else if (CHECK_ONLY) {
        status = 'installable';
        action = '未安装，将安装 ' + lat;
      } else {
        out('  … 正在安装 ' + t.name + ' (' + t.pkg + '@' + lat + ')');
        const res = npm(['install', '-g', '--no-fund', '--no-audit', t.pkg + '@latest'], 600000);
        if (!res.error && res.status === 0) {
          status = 'installed'; verFrom = '-'; verTo = installedVersion(t.pkg) || lat;
          action = '已安装 ' + verTo;
        } else {
          status = 'error'; action = '安装失败';
          err = extractErr(res, t);
        }
      }
    } else if (cur === lat) {
      status = 'ok'; action = '已是最新';
    } else if (CHECK_ONLY) {
      status = 'upgradable'; action = '可升级 ' + cur + ' → ' + lat;
    } else {
      out('  … 正在升级 ' + t.name + ' ' + cur + ' → ' + lat);
      const res = npm(['install', '-g', '--no-fund', '--no-audit', t.pkg + '@latest'], 600000);
      if (!res.error && res.status === 0) {
        status = 'upgraded'; verTo = installedVersion(t.pkg) || lat;
        action = '已升级 ' + cur + ' → ' + verTo;
      } else {
        status = 'error'; action = '升级失败（仍为 ' + cur + '）';
        err = extractErr(res, t);
      }
    }

    bump(status);

    const icon = { ok: '✓', upgradable: '!', installable: '!', upgraded: '↑', installed: '↑', external: '○', unknown: '?' }[status] || '✗';
    out([t.id.padEnd(9), (icon + ' ' + status).padEnd(13), String(verFrom).padEnd(11), String(verTo).padEnd(11), action].join(''));
    if (err) out('          错误详情: ' + sanitize(err));

    results.push({ id: t.id, name: t.name, status: status, installed: verFrom, latest: verTo, action: action, error: sanitize(err) });
  }

  out('--------------------------------------------------------------');
  out('汇总: ' + [
    (summary.ok || 0) + ' 已最新',
    ((summary.upgradable || 0) + (summary.installable || 0) + (summary.upgraded || 0)) + ' 升级(或待处理)',
    (summary.installed || 0) + ' 新装',
    (summary.external || 0) + ' 外部渠道',
    (summary.unknown || 0) + ' 未知',
    (summary.error || 0) + ' 失败',
  ].join(' / '));

  if (EMIT_JSON) {
    out('##JSON##' + JSON.stringify({
      checked_at: new Date().toISOString(),
      check_only: CHECK_ONLY,
      results: results,
      summary: summary,
    }));
  }

  process.exit((summary.error || 0) > 0 ? 1 : 0);
}

function extractErr(res, t) {
  if (res.error) {
    if (res.error.code === 'ETIMEDOUT') return '执行超时';
    return res.error.message || String(res.error);
  }
  const tail = String(res.stderr || res.stdout || '').trim().split('\n').slice(-3).join(' ');
  if (/EACCES|permission denied/i.test(tail)) return eaccHint(t.pkg) + ' | ' + tail;
  return tail || ('npm 退出码 ' + res.status);
}

main();
";

let runtimeCtx = null;

function manualHint(flags) {
  return '手动执行等价命令: node <仓库>/foxai_update/scripts/update-cli-tools.js ' + flags.join(' ');
}

function tail(text, n) {
  const s = String(text || '');
  return s.length > n ? '…' + s.slice(-n) : s;
}

function parseJsonLine(text) {
  const lines = String(text || '').split('
');
  for (let i = lines.length - 1; i >= 0; i--) {
    const idx = lines[i].indexOf('##JSON##');
    if (idx !== -1) {
      try {
        return JSON.parse(lines[i].slice(idx + 8));
      } catch (e) {
        return null;
      }
    }
  }
  return null;
}

function readCollected(handle, stream) {
  try {
    const c = handle.collected && handle.collected[stream];
    if (!c || typeof c.readFrom !== 'function') return '';
    const r = c.readFrom(0);
    if (typeof r === 'string') return r;
    if (r && typeof r.text === 'string') return r.text;
    if (r && typeof r.data === 'string') return r.data;
    return r ? String(r) : '';
  } catch (e) {
    return '';
  }
}

function getSubprocess() {
  if (!runtimeCtx) return null;
  try {
    if (typeof runtimeCtx.get === 'function') {
      const s = runtimeCtx.get('subprocess');
      if (s) return s;
    }
  } catch (e) {  }
  try {
    if (runtimeCtx.subprocess) return runtimeCtx.subprocess;
  } catch (e) {  }
  return null;
}

async function runUpdateScript(flags) {
  const sub = getSubprocess();
  if (!sub || typeof sub.resolveExecutable !== 'function' || typeof sub.spawn !== 'function') {
    return {
      success: false,
      error: 'subprocess 服务不可用（插件宿主未挂载 @deepseek-ai/dsh-subprocess-local）',
      hint: manualHint(flags),
    };
  }

  let nodeExe;
  try {
    nodeExe = await sub.resolveExecutable('node');
  } catch (e) {
    return { success: false, error: '未找到 node 可执行文件: ' + String((e && e.message) || e), hint: manualHint(flags) };
  }

  const argv = [nodeExe, '-e', UPDATE_SCRIPT, '--'].concat(flags);
  let handle;
  try {
    handle = sub.spawn({
      argv: argv,

      cwd: runtimeCtx && runtimeCtx.cwd ? runtimeCtx.cwd : (process && process.cwd ? process.cwd() : '.'),
      stdio: {
        stdin: 'ignore',
        stdout: { maxBytes: 4 * 1024 * 1024 },
        stderr: { maxBytes: 512 * 1024 },
      },

      graceMs: 10 * 60 * 1000,
    });
  } catch (e) {
    return { success: false, error: 'spawn 失败: ' + String((e && e.message) || e), hint: manualHint(flags) };
  }

  let done;
  try {
    done = await handle.done;
  } catch (e) {
    return { success: false, error: '进程未能启动: ' + String((e && e.message) || e), hint: manualHint(flags) };
  }

  const stdoutText = readCollected(handle, 'stdout');
  const stderrText = readCollected(handle, 'stderr');
  const parsed = parseJsonLine(stdoutText);
  if (parsed) {
    return Object.assign({ success: true, exit_code: done.exitCode, output_tail: tail(stdoutText, 1500) }, parsed);
  }
  return {
    success: false,
    exit_code: done.exitCode,
    error: '未能从脚本输出解析 ##JSON## 结果',
    output_tail: tail(stdoutText, 1500),
    stderr_tail: tail(stderrText, 800),
    hint: manualHint(flags),
  };
}

function defineUpdateTool() {
  return harness.defineTool({
    name: 'foxai_cli_update',
    description:
      '检查并安装/升级 5 款 AI CLI 编码工具（Claude Code、Codex CLI、Gemini CLI、OpenCode、Pi）。' +
      '未安装的自动通过 npm 全局安装，已安装但有新版的自动升级到最新；非 npm 渠道（brew 等）安装的会识别并跳过。' +
      '默认执行更新；设置 check_only=true 则仅检查报告、不做任何改动。跨 macOS/Linux/Windows。',
    parameters: {
      type: 'object',
      properties: {
        check_only: {
          type: 'boolean',
          description: '仅检查并报告各工具状态，不安装/不升级（默认 false，即执行更新）',
          default: false,
        },
        tools: {
          type: 'array',
          items: { type: 'string', enum: ['claude', 'codex', 'gemini', 'opencode', 'pi'] },
          description: '只处理这些工具（默认全部 5 个）',
        },
      },
      required: [],
    },
    async execute(args) {
      const a = args || {};
      const flags = [];
      if (a.check_only) flags.push('--check');
      if (Array.isArray(a.tools) && a.tools.length) flags.push('--only=' + a.tools.join(','));
      flags.push('--json');
      try {
        const res = await runUpdateScript(flags);
        if (res && res.summary && !res.check_only) {
          res.message = '已执行更新。汇总: ' + JSON.stringify(res.summary);
        } else if (res && res.summary) {
          res.message = '检查完成（未做改动）。汇总: ' + JSON.stringify(res.summary);
        }
        return res;
      } catch (err) {
        return { success: false, error: String((err && err.message) || err), hint: manualHint(flags) };
      }
    },
  });
}

const tool = defineUpdateTool();
const disposers = [];
disposers.push(harness.registerTool(ctx, tool));

return {
  inject: ['harness'],
  apply(applyCtx) {
    runtimeCtx = applyCtx;
    applyCtx.effect(function () {
      return function () {
        runtimeCtx = null;
        for (const d of disposers) {
          try { d(); } catch (e) {}
        }
      };
    });
    console.log('[foxai_cli_update] 已注册工具 foxai_cli_update（AI CLI 检查/安装/升级）');
  },
};

